import { renderRequest } from '/home/user/deepseek-harness/packages/llm/llm-claude-code/lib/index.js'

const z = zodModule.z ?? zodModule
const here = new URL('.', import.meta.url).pathname
const [label = 'mcp', model = 'sonnet', effortArg = 'medium'] = process.argv.slice(2)
const system = readFileSync(`${here}system.txt`, 'utf8')
const user = readFileSync(`${here}user.txt`, 'utf8')
const tools = JSON.parse(readFileSync(`${here}tools.json`, 'utf8'))
const rendered = renderRequest({
  model,
  system,
  messages: [{ role: 'user', content: [{ type: 'text', text: user }] }],
  tools: [],
})
const captured = []
const started = Date.now()
const log = (...parts) => console.log(`[${label} +${((Date.now() - started) / 1000).toFixed(1)}s]`, ...parts)
const definitions = tools.map((definition) => {
  const object = z.fromJSONSchema(definition.parameters)
  return tool(definition.name, definition.description, object.shape, async (input) => {
    captured.push({ name: definition.name, input })
    log('handler', definition.name, JSON.stringify(input).slice(0, 200))
    return { content: [{ type: 'text', text: 'queued' }] }
  })
})
const server = createSdkMcpServer({ name: 'dsh', version: '0.0.0', tools: definitions })
const q = query({
  prompt: rendered.prompt,
  options: {
    systemPrompt: rendered.systemPrompt,
    includePartialMessages: false,
    maxTurns: 1,
    permissionMode: 'dontAsk',
    tools: [],
    allowedTools: tools.map(definition => `mcp__dsh__${definition.name}`),
    disallowedTools: ['AskUserQuestion'],
    mcpServers: { dsh: server },
    strictMcpConfig: true,
    settingSources: [],
    persistSession: false,
    model,
    ...(effortArg === 'none' ? {} : { effort: effortArg }),
  },
})
try {
  for await (const message of q) {
    if (message.type === 'assistant') {
      const blocks = message.message.content.map((block) => {
        if (block.type === 'text') return `text(${block.text.length}): ${JSON.stringify(block.text.slice(0, 160))}`
        if (block.type === 'tool_use') return `tool_use ${block.name} ${JSON.stringify(block.input).slice(0, 200)}`
        if (block.type === 'thinking') return `thinking(${(block.thinking ?? '').length})`
        return block.type
      })
      log('assistant', `stop=${message.message.stop_reason}`, `usage=${JSON.stringify(message.message.usage)}`, blocks.join(' | '))
    } else if (message.type === 'user') {
      const content = message.message.content
      const summary = Array.isArray(content)
        ? content.map(b => b.type === 'tool_result' ? `tool_result(${JSON.stringify(b.content).slice(0, 200)})` : `${b.type}:${JSON.stringify(b.text ?? '').slice(0, 200)}`).join(' | ')
        : JSON.stringify(content).slice(0, 200)
      log('user', summary)
    } else if (message.type === 'result') {
      log('result', message.subtype, `turns=${message.num_turns}`, `is_error=${message.is_error}`, `stop=${message.stop_reason ?? ''}`,
        `errors=${JSON.stringify(message.errors ?? [])}`, `result=${JSON.stringify(message.result ?? null).slice(0, 200)}`,
        `usage=${JSON.stringify(message.usage).slice(0, 300)}`)
    } else if (message.type === 'system' && message.subtype === 'init') {
      log('init', `model=${message.model}`, `tools=${JSON.stringify(message.tools)}`, `mcp=${JSON.stringify(message.mcp_servers)}`)
    } else {
      log(message.type, message.subtype ?? '')
    }
  }
  log('done', `captured=${JSON.stringify(captured).slice(0, 400)}`)
} catch (error) {
  log('THROW', error instanceof Error ? error.message : String(error), `captured=${JSON.stringify(captured).slice(0, 400)}`)
}

