    const offer = toolOffer([BASH_TOOL])
    expect(offer?.server).toMatchObject({ type: 'sdk', name: MCP_SERVER_NAME })
    expect(offer?.allowedTools).toEqual([`${MCP_TOOL_PREFIX}bash`])
